GTCEuStartupEvents.registry('gtceu:recipe_type', event => {
    event.create('nuclear_dissolvant')
    .setMaxIOSize(1, 1, 2, 4)
    .category('nuclear')
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.ATOMIC_OVERLAY_2)
    .setProgressBar(GuiTextures.PROGRESS_BAR_ARROW_MULTIPLE, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.ELECTROLYZER)

    event.create('extraction_column')
    .setMaxIOSize(0, 0, 2, 2)
    .category('nuclear')
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.ATOMIC_OVERLAY_2)
    .setProgressBar(GuiTextures.PROGRESS_BAR_FUSION, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.CHEMICAL)

    event.create('scrubbing_column')
    .setMaxIOSize(0, 0, 2, 2)
    .category('nuclear')
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.ATOMIC_OVERLAY_2)
    .setProgressBar(GuiTextures.PROGRESS_BAR_FUSION, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.SPRAY_CAN_TOOL)

    event.create('partition_column')
    .setMaxIOSize(0, 0, 2, 2)
    .category('nuclear')
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.ATOMIC_OVERLAY_2)
    .setProgressBar(GuiTextures.PROGRESS_BAR_FUSION, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.SPRAY_CAN_TOOL)
    
    event.create('stripping_column')
    .setMaxIOSize(0, 0, 2, 2)
    .category('nuclear')
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.ATOMIC_OVERLAY_2)
    .setProgressBar(GuiTextures.PROGRESS_BAR_FUSION, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.SPRAY_CAN_TOOL)

    event.create('nuclear_turbine')
    .category('nuclear')
    .setMaxIOSize(0, 0, 1, 1)
    .setSlotOverlay(true, true, GuiTextures.TURBINE_OVERLAY)
    .setProgressBar(GuiTextures.PROGRESS_BAR_GAS_COLLECTOR, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.JET_ENGINE)

    event.create('nuclear_fission')
    .category('nuclear')
    .setMaxIOSize(1, 1, 1, 1)
    .setEUIO('in')
    .setSlotOverlay(true, true, GuiTextures.TURBINE_OVERLAY)
    .setProgressBar(GuiTextures.PROGRESS_BAR_GAS_COLLECTOR, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.JET_ENGINE)

    event.create('supercritical_fission')
    .setEUIO('out')
    .category('supernuclear')
    .setMaxIOSize(2,1,0,1)
    .setSlotOverlay(true, true, GuiTextures.VIAL_OVERLAY_1)
    .setProgressBar(GuiTextures.PROGRESS_BAR_ARROW_MULTIPLE, FillDirection.LEFT_TO_RIGHT)
    .setSound(GTSoundEntries.JET_ENGINE)
})

